def forward(groups):
    date_part = groups[0]
    time_part = f"{groups[1]}:{groups[2]}:{groups[3]}.{groups[4]}"
    dt = datetime.strptime(f"{date_part} {time_part}", "%Y%m%d %H:%M:%S.%f")
    return {'stored': [int(dt.timestamp() * 1000)], 'layout': []}

def inverse(record):
    millis = int(record['stored'][0])
    dt = datetime.fromtimestamp(millis / 1000)
    return dt.strftime("%Y%m%d-%H:%M:%S:%f")[:-3]

